const PLUGIN_ID = "qwen-custom-voice-tts-plugin";
const VOICE_CATALOG = [
  {
    alias: "ve_03_02",
    model: "cosyvoice-v3.5-plus",
    voiceId: "cosyvoice-v3.5-plus-bailian-c89f64152a2f44c4b5127766ab4cc10c",
  },
  {
    alias: "ve_04_01",
    model: "cosyvoice-v3.5-plus",
    voiceId: "cosyvoice-v3.5-plus-bailian-968248e6a5614af3a77503c96e744ef1",
  },
  {
    alias: "ve_02",
    model: "qwen-audio-3.0-tts-plus",
    voiceId: "qwen-audio-3.0-tts-plus-bailian-692b6df2b2664d5d827a4b67d4950c84",
  },
  {
    alias: "ve_03_02",
    model: "qwen-audio-3.0-tts-plus",
    voiceId: "qwen-audio-3.0-tts-plus-bailian-f88a8fc60f6b4fb589a86487e99d1706",
  },
  {
    alias: "ve_04_01",
    model: "qwen-audio-3.0-tts-plus",
    voiceId: "qwen-audio-3.0-tts-plus-bailian-187e9642335d446a97d02313ee998cce",
  },
];

const normalizeBaseUrl = (baseUrl) => {
  return (baseUrl || "https://dashscope.aliyuncs.com/api/v1").replace(/\/+$/, "");
};

const log = (config, ...args) => {
  if (!config || config.debug !== "no") {
    console.log("[Aliyun Custom Voice TTS]", ...args);
  }
};

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const shouldRetryDownload = (error) => {
  const transientCodes = [
    "ECONNRESET", "ETIMEDOUT", "ECONNABORTED", "EAI_AGAIN", "ENOTFOUND",
  ];
  const status = error && error.response && error.response.status;
  return transientCodes.includes(error && error.code) || status >= 500;
};

const postWithRetry = async (url, body, options, config, axios, label) => {
  const maxAttempts = clamp(parseInt(config.requestRetryCount || "3", 10) || 3, 1, 5);
  const timeout = clamp(parseInt(config.requestTimeout || "90000", 10) || 90000, 10000, 300000);
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      log(config, `${label} post`, { attempt, maxAttempts, timeout });
      return await axios.post(url, body, { ...options, timeout });
    } catch (error) {
      const retryable = shouldRetryDownload(error);
      log(config, `${label} post failed`, {
        attempt, maxAttempts, retryable,
        code: error && error.code,
        status: error && error.response && error.response.status,
        message: error && error.message,
      });
      if (!retryable || attempt >= maxAttempts) throw error;
      await sleep(500 * attempt);
    }
  }
  throw new Error(`${label} post failed`);
};

const downloadAudioWithRetry = async (audioUrl, config, axios) => {
  const safeAudioUrl = audioUrl.replace(/^http:\/\//, "https://");
  const maxAttempts = clamp(parseInt(config.downloadRetryCount || "3", 10) || 3, 1, 5);
  const timeout = clamp(parseInt(config.downloadTimeout || "90000", 10) || 90000, 10000, 300000);
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      log(config, "download audio", { attempt, maxAttempts, timeout });
      const response = await axios.get(safeAudioUrl, { responseType: "arraybuffer", timeout });
      const buffer = Buffer.from(response.data);
      log(config, "download audio success", { attempt, byteLength: buffer.length });
      return buffer;
    } catch (error) {
      const retryable = shouldRetryDownload(error);
      log(config, "download audio failed", {
        attempt, maxAttempts, retryable,
        code: error && error.code,
        status: error && error.response && error.response.status,
        message: error && error.message,
      });
      if (!retryable || attempt >= maxAttempts) throw error;
      await sleep(500 * attempt);
    }
  }
  throw new Error("Download audio failed");
};

const parseLanguageHints = (config) => {
  return String(config.languageHints || "zh").split(",").map((item) => item.trim()).filter(Boolean);
};

const getTTSAudio = async (text, speed, config) => {
  if (!config.apiKey) throw new Error("Missing DashScope apiKey");
  const voice = VOICE_CATALOG.find((item) => item.voiceId === config.voiceName && item.model === config.model);
  if (!voice) throw new Error("Unknown or mismatched Aliyun custom voice");
  const axios = require("axios");
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const speedDelta = Number(speed);
  const input = {
    text,
    voice: voice.voiceId,
    format: config.format || "wav",
    sample_rate: parseInt(config.sampleRate || "24000", 10) || 24000,
    volume: clamp(parseInt(config.volume || "50", 10), 0, 100),
    pitch: clamp(parseFloat(config.pitch || "1.0") || 1.0, 0.5, 2.0),
    rate: clamp(Number.isFinite(speedDelta) ? (speedDelta + 100) / 100 : 1.0, 0.5, 2.0),
    language_hints: parseLanguageHints(config),
    seed: 0,
  };
  if (config.instruction) input.instruction = config.instruction;
  log(config, "synthesis request", {
    baseUrl, model: voice.model, voice: voice.alias,
    rate: input.rate, languageHints: input.language_hints, textLength: text.length,
  });
  const response = await postWithRetry(
    `${baseUrl}/services/audio/tts/SpeechSynthesizer`,
    { model: voice.model, input },
    { headers: { Authorization: `Bearer ${config.apiKey}`, "Content-Type": "application/json" } },
    config, axios, "synthesis",
  );
  const output = response.data && response.data.output;
  if (!output || output.finish_reason !== "stop" || !output.audio || !output.audio.url) {
    throw new Error("No complete audio URL in Aliyun TTS response");
  }
  log(config, "synthesis completed", { requestId: response.data.request_id });
  return await downloadAudioWithRetry(output.audio.url, config, axios);
};

const getAudioPath = async (text, speed, dirPath, config) => {
  const path = require("path");
  const fs = require("fs");
  const audioName = `${new Date().getTime()}.${config.format || "wav"}`;
  const ttsDir = path.join(dirPath, "tts");
  if (!fs.existsSync(ttsDir)) fs.mkdirSync(ttsDir);
  const audioData = await getTTSAudio(text, speed, config);
  const audioPath = path.join(ttsDir, audioName);
  fs.writeFileSync(audioPath, audioData);
  return audioPath;
};

const getTTSVoice = async (config) => {
  if (!config.apiKey) throw new Error("Missing DashScope apiKey");
  const axios = require("axios");
  const baseUrl = normalizeBaseUrl(config.baseUrl);
  const pageSize = clamp(parseInt(config.pageSize || "100", 10) || 100, 1, 100);
  const available = new Set();
  for (let pageIndex = 0; ; pageIndex++) {
    const response = await postWithRetry(
      `${baseUrl}/services/audio/tts/customization`,
      { model: "voice-enrollment", input: { action: "list_voice", page_size: pageSize, page_index: pageIndex } },
      { headers: { Authorization: `Bearer ${config.apiKey}`, "Content-Type": "application/json" } },
      config, axios, "voice list",
    );
    const page = response.data && response.data.output && response.data.output.voice_list;
    if (!Array.isArray(page)) throw new Error("Invalid Aliyun voice list response");
    for (const voice of page) {
      if (voice.status === "OK") available.add(voice.voice_id);
    }
    log(config, "voice list page", { pageIndex, count: page.length });
    if (page.length < pageSize) break;
  }
  const voices = VOICE_CATALOG.filter((voice) => available.has(voice.voiceId)).map((voice) => ({
    name: voice.voiceId,
    gender: "unknown",
    locale: "zh-CN",
    displayName: `${voice.model} ${voice.alias}`,
    plugin: PLUGIN_ID,
    config: { ...config, voiceName: voice.voiceId, model: voice.model },
  }));
  if (voices.length === 0) throw new Error("No configured Aliyun voices are available for this API key");
  log(config, "custom voices loaded", { count: voices.length, voices: voices.map((voice) => voice.displayName) });
  return voices;
};

global.getAudioPath = getAudioPath;
global.getTTSVoice = getTTSVoice;
